import DSA5_Utility from '../../system/helpers/utility-dsa5.js';
import NavalBroadsideDialog from '../../dialog/naval-broadside-dialog.js';
import NavalBoardWeapons from './naval-board-weapons.js';
import NavalCombat from './naval-combat.js';
import NavalCombatDamage from './naval-combat-damage.js';

const { duplicate, randomID } = foundry.utils;
const { renderTemplate } = foundry.applications.handlebars;

/**
 * Volle Breitseite: multi-select board guns, silent multi-fire, one summary chat card.
 */
export default class NavalBroadside {
  static register() {
    Hooks.on('renderChatMessageHTML', this.onRenderChatMessage.bind(this));
  }

  static maxShots(weapon, combat = game.combat) {
    const rate = NavalBoardWeapons.shotsPerMkr(weapon, combat);
    if (!Number.isFinite(rate) || rate <= 0) return 1;
    return Math.max(1, Math.ceil(rate));
  }

  static usedShots(combatant, weaponId) {
    return Number(combatant?.system?.broadsideShots?.[weaponId]) || 0;
  }

  static remainingShots(weapon, combatant, combat = game.combat) {
    const max = this.maxShots(weapon, combat);
    return Math.max(0, max - this.usedShots(combatant, weapon.id));
  }

  static resolveCombatant(vehicle, combat = game.combat) {
    if (!combat || !vehicle) return null;
    return combat.combatants.find((c) => c.actorId === vehicle.id)
      ?? combat.combatants.find((c) => c.actor?.id === vehicle.id)
      ?? null;
  }

  static async open(vehicle, { tokenId } = {}) {
    if (!vehicle) return;

    if (!NavalBoardWeapons.canFireInMkr()) {
      ui.notifications.warn('VEHICLE.boardWeaponAttacksPhaseOnly', { localize: true });
      return;
    }

    if (!game.user.targets.size) {
      ui.notifications.warn('VEHICLE.mkr.pickTargetFirst', { localize: true });
      return;
    }

    const hasWornGun = vehicle.items.some((i) => i.type === 'rangeweapon' && i.system?.worn?.value);
    if (!hasWornGun) {
      ui.notifications.warn('VEHICLE.mkr.broadsideNoWeapons', { localize: true });
      return;
    }

    const selection = await NavalBroadsideDialog.prompt(vehicle, { tokenId });
    if (!selection?.length) return;

    await this.execute(vehicle, selection, { tokenId });
  }

  static async execute(vehicle, selection, { tokenId } = {}) {
    const combat = game.combat;
    const combatant = this.resolveCombatant(vehicle, combat);
    const targets = [...game.user.targets];
    if (!targets.length) {
      ui.notifications.warn('VEHICLE.mkr.pickTargetFirst', { localize: true });
      return;
    }

    const primaryTarget = targets.find((t) => t.actor?.type === 'vehicle') ?? targets[0];
    const defenderVehicle = primaryTarget.actor?.type === 'vehicle' ? primaryTarget.actor : null;

    const shots = [];
    const budgetUpdates = {};

    const sourceToken = tokenId
      ? canvas.tokens?.get(tokenId)
      : canvas.tokens?.placeables.find((t) => t.actor?.id === vehicle.id);

    for (const entry of selection) {
      const item = vehicle.items.get(entry.weaponId);
      if (!item) continue;

      if (!NavalBroadsideDialog.isWeaponInRange(item, sourceToken, game.user.targets)) continue;

      const remaining = combatant
        ? this.remainingShots(item, combatant, combat)
        : this.maxShots(item, combat);
      const toFire = Math.min(entry.shots, remaining);
      if (toFire <= 0) continue;

      const operatorUuid = vehicle.system.weaponOperators?.[item.id];
      let fired = 0;

      for (let i = 0; i < toFire; i++) {
        const shot = await this.#fireOneShot(vehicle, item, {
          tokenId,
          operatorUuid,
          skipReadyCheck: i > 0,
          defenderVehicle,
        });
        if (!shot) break;
        shots.push(shot);
        fired++;
      }

      if (fired > 0 && combatant) {
        const already = this.usedShots(combatant, item.id);
        budgetUpdates[`system.broadsideShots.${item.id}`] = already + fired;
      }
    }

    if (combatant && Object.keys(budgetUpdates).length) {
      await combatant.update(budgetUpdates);
    }

    if (!shots.length) {
      ui.notifications.warn('VEHICLE.mkr.broadsideNoShots', { localize: true });
      return;
    }

    await this.#postSummary(vehicle, primaryTarget, defenderVehicle, shots);
  }

  static async #fireOneShot(vehicle, item, { tokenId, operatorUuid, skipReadyCheck, defenderVehicle }) {
    const liveItem = vehicle.items.get(item.id) ?? item;
    const setup = await NavalBoardWeapons.resolveFireSetup(vehicle, liveItem, 'attack', {
      tokenId,
      operatorUuid,
      skipReadyCheck,
    });
    if (!setup) return null;

    const options = {
      ...setup.options,
      bypass: true,
    };

    const setupData = await setup.rollingActor.setupWeapon(liveItem, 'attack', options, tokenId);
    if (!setupData) return null;

    // Bypass skips the dialog callback — apply selected dialog modifiers.
    const dialogMods = setupData.dialogOptions?.data?.situationalModifiers;
    if (dialogMods?.length) {
      setupData.testData.situationalModifiers = dialogMods.filter((m) => m.selected !== false);
    } else {
      setupData.testData.situationalModifiers ??= [];
    }

    const rolled = await setup.rollingActor.basicTest(setupData, { suppressMessage: true });
    if (!rolled?.result) return null;

    const result = rolled.result;
    let hit = (result.successLevel ?? 0) > 0;
    let evadeBlocked = false;

    if (hit && defenderVehicle && this.#isEvadeBlocked(result, defenderVehicle)) {
      hit = false;
      evadeBlocked = true;
    }

    const attackerPayload = {
      speaker: setupData.testData.extra.speaker,
      testResult: { ...result, source: setupData.testData.source },
      options: setup.options,
    };

    const stpFormula = hit && defenderVehicle
      ? NavalCombatDamage.resolveStpFormula(attackerPayload, defenderVehicle)
      : null;

    return {
      id: randomID(),
      weaponId: item.id,
      weaponName: item.name,
      hit,
      evadeBlocked,
      successLevel: result.successLevel ?? 0,
      qualityStep: result.qualityStep ?? 0,
      damage: result.damage ?? null,
      damagedescription: result.damagedescription ?? '',
      description: result.description ?? '',
      stpFormula,
      attackerName: setup.rollingActor.name,
      detailsHtml: this.#buildDetailsHtml(result, rolled.cardOptions?.title ?? item.name),
      queued: false,
    };
  }

  static #isEvadeBlocked(result, defenderVehicle) {
    if (!NavalCombat.isNavalMkrActive()) return false;
    if (game.combat?.system?.mkrPhase !== 'attacks') return false;

    const maneuver = NavalCombatDamage.getManeuver(game.combat, defenderVehicle.id);
    if (maneuver?.maneuverType !== 'evade') return false;

    const penalty = Math.min(6, maneuver.maneuverQS || 0);
    const attSL = result?.successLevel ?? 0;
    return attSL - penalty <= -5;
  }

  static #buildDetailsHtml(result, title) {
    const chars = (result.characteristics || [])
      .map((c) => `<span class="${c.suc ? 'suc' : 'fail'}">${c.res}</span>`)
      .join(' ');
    const parts = [
      `<b>${Handlebars.escapeExpression(String(title ?? ''))}</b>`,
      chars ? `<div><b>${_loc('Roll')}</b>: ${chars}</div>` : '',
      result.modifiers != null ? `<div><b>${_loc('Modifiers')}</b>: ${result.modifiers}</div>` : '',
      result.qualityStep != null ? `<div><b>${_loc('qualityStep')}</b>: ${result.qualityStep}</div>` : '',
      result.damage != null ? `<div><b>${_loc('damage')}</b>: ${result.damage}</div>` : '',
      result.description ? `<div><b>${_loc('Description')}</b>: ${result.description}</div>` : '',
    ];
    return parts.filter(Boolean).join('');
  }

  static async #postSummary(vehicle, primaryTarget, defenderVehicle, shots) {
    const hits = shots.filter((s) => s.hit && s.stpFormula);
    let stpPreviewTotal = 0;
    for (const hit of hits) {
      try {
        const roll = await new Roll(String(hit.stpFormula)).evaluate();
        hit.stpPreview = roll.total;
        stpPreviewTotal += roll.total;
      } catch {
        hit.stpPreview = null;
      }
    }

    const content = await renderTemplate('systems/dsa5/templates/chat/roll/naval-broadside-card.hbs', {
      vehicleName: vehicle.name,
      targetName: primaryTarget?.name ?? primaryTarget?.document?.name ?? '—',
      shotCount: shots.length,
      hitCount: shots.filter((s) => s.hit).length,
      shots,
      canQueue: !!defenderVehicle,
      stpPreviewTotal,
      hasUnqueuedHits: hits.some((h) => !h.queued),
    });

    const chatData = DSA5_Utility.chatDataSetup(content);
    chatData.flags = {
      dsa5: {
        broadside: {
          vehicleId: vehicle.id,
          targetId: defenderVehicle?.id ?? primaryTarget?.actor?.id ?? null,
          targetTokenId: primaryTarget?.id ?? null,
          hits: shots.map((s) => ({
            id: s.id,
            weaponId: s.weaponId,
            weaponName: s.weaponName,
            hit: s.hit,
            stpFormula: s.stpFormula,
            attackerName: s.attackerName,
            queued: false,
          })),
        },
      },
    };

    await ChatMessage.create(chatData);
  }

  static onRenderChatMessage(app, html, msg) {
    const message = msg?.message ?? app;
    const root = html instanceof HTMLElement ? html : html?.[0] ?? html;
    if (!root?.querySelector?.('.naval-broadside-card')) return;

    root.querySelectorAll('.naval-broadside-queue-one').forEach((button) => {
      button.addEventListener('click', async (ev) => {
        ev.preventDefault();
        const hitId = button.dataset.hitId;
        if (!message || !hitId) return;
        await this.#queueHits(message, [hitId], root.querySelector('.naval-broadside-card'));
      });
    });

    root.querySelector('.naval-broadside-queue-all')?.addEventListener('click', async (ev) => {
      ev.preventDefault();
      if (!message) return;
      await this.#queueHits(message, null, root.querySelector('.naval-broadside-card'));
    });
  }

  static async #queueHits(message, hitIds, cardEl) {
    if (!NavalCombat.isNavalMkrActive()) {
      ui.notifications.warn('VEHICLE.mkr.broadsideQueuePhaseOnly', { localize: true });
      return;
    }
    if (game.combat?.system?.mkrPhase !== 'attacks') {
      ui.notifications.warn('VEHICLE.mkr.broadsideQueuePhaseOnly', { localize: true });
      return;
    }

    const payload = duplicate(message.flags?.dsa5?.broadside ?? {});
    const target = game.actors.get(payload.targetId);
    if (!target || target.type !== 'vehicle') {
      ui.notifications.warn('VEHICLE.mkr.broadsideNoVehicleTarget', { localize: true });
      return;
    }

    const toQueue = (payload.hits ?? []).filter((h) => {
      if (!h.hit || !h.stpFormula || h.queued) return false;
      if (hitIds && !hitIds.includes(h.id)) return false;
      return true;
    });

    if (!toQueue.length) {
      ui.notifications.info('VEHICLE.mkr.broadsideNothingToQueue', { localize: true });
      return;
    }

    for (const hit of toQueue) {
      await NavalCombatDamage.queueHit(target, hit.stpFormula, hit.attackerName);
      hit.queued = true;
      const row = cardEl?.querySelector(`[data-hit-id="${hit.id}"]`);
      if (row) {
        row.classList.add('queued');
        row.querySelector('.naval-broadside-queue-one')?.remove();
        const status = row.querySelector('.naval-broadside-queue-status');
        if (status) status.textContent = _loc('VEHICLE.mkr.broadsideQueued');
      }
    }

    await message.update({ 'flags.dsa5.broadside': payload });

    if (cardEl && (payload.hits ?? []).every((h) => !h.hit || !h.stpFormula || h.queued)) {
      cardEl.querySelector('.naval-broadside-queue-all')?.remove();
    }

    ui.notifications.info(_loc('VEHICLE.mkr.broadsideQueuedCount', { count: toQueue.length }));
  }
}
