import DialogShared from '../../dialog/dialog-shared.js';
import DSA5 from '../../config/config-dsa5.js';
import CreatureType from './creature-type.js';
import DiceDSA5 from '../rolls/dice-dsa5.js';
import DSA5_Utility from '../helpers/utility-dsa5.js';

const { getProperty } = foundry.utils;
const { renderTemplate } = foundry.applications.handlebars;

export default class EquipmentDamage {
  static armorWearModifier(armorData, armorValue) {
    if (game.settings.get('dsa5', 'armorAndWeaponDamage')) {
      switch (EquipmentDamage.calculateWear(armorData)) {
        case 1:
        case 2:
          armorValue -= 1;
          break;
        case 3:
        case 4:
          armorValue = 0;
      }
    }
    return Math.max(0, Number(armorValue));
  }

  static armorGetsDamage(damage, attackData) {
    return (damage > 14 || attackData.successLevel > 2) && game.settings.get('dsa5', 'armorAndWeaponDamage');
  }

  static armorEncumbranceModifier(armor) {
    if (game.settings.get('dsa5', 'armorAndWeaponDamage')) {
      if (EquipmentDamage.calculateWear(armor) > 1) return 1;
    }
    return 0;
  }

  static async showDamageToGear(preData, testData) {
    if (game.settings.get('dsa5', 'armorAndWeaponDamage')) {
      let actor = DSA5_Utility.getSpeaker(preData.extra.speaker);
      let attackSuccessLevel = 0;
      const opposeMessageId = getProperty(actor, 'flags.oppose.messageId');
      if (opposeMessageId) {
        const attackMessage = game.messages.get(opposeMessageId);
        if (attackMessage) attackSuccessLevel = getProperty(attackMessage, 'flags.data.postData.successLevel') || 0;
      }

      const source = preData.source;
      if (source._id && source.system.structure && (testData.successLevel < -2 || attackSuccessLevel > 2) && ['meleeweapon', 'rangeweapon', 'armor'].includes(source.type)) {
        actor = await DSA5_Utility.getSpeaker(testData.speaker);
        return actor.items.get(source._id).uuid;
      }
    }
    return undefined;
  }

  static breakingTest(item) {
    if (!item)
      return ui.notifications.warn(
        'DSAError.notFound', { localize: true, format: {
          category: '',
          name: _loc('TYPES.Item.equipment'),
        }});
    if (item.system.structure.max <= 0) return ui.notifications.warn('DSAError.noBreakingStructure', { format: { name: item.name }, localize: true });

    let breakingResistance = 0;
    let category;
    if (item.type == 'armor') {
      category = _loc(`ARMORSUBCATEGORIES.${item.system.subcategory}`);
      breakingResistance = item.system.structure.breakPointRating || DSA5.armorSubcategories[item.system.subcategory];
    } else {
      category = item.system.combatskill.value;
      breakingResistance = item.system.structure.breakPointRating || DSA5.weaponStabilities[_loc(`LocalizedCTs.${category}`)];
    }
    if (!breakingResistance) {
      ui.notifications.error('DSAError.noBreakingResistance', { format: { item: item.name }, localize: true });
      return;
    }

    let magicalWarning = '';
    const attributes = getProperty(item, 'effect.attributes') || '';

    if (new RegExp(`${CreatureType.magical}`, 'i').test(attributes)) magicalWarning = `${_loc('WEAPON.attributeWarning', { domain: CreatureType.clerical })}<br/>`;
    else if (new RegExp(`${CreatureType.clerical}`, 'i').test(attributes)) magicalWarning = `${_loc('WEAPON.attributeWarning', { domain: CreatureType.magical })}<br/>`;

    new DialogShared({
      window: { title: 'DSASETTINGS.armorAndWeaponDamage' },
      content: `${magicalWarning}<label for="threshold">${_loc('WEAR.check', {
        category,
      })}</label>: <input class="quantity-click" style="width:80px" dtype="number" name="threshold" type="number" value="${breakingResistance}"/>`,
      buttons: [
        {
          action: 'yes',
          icon: 'fas fa-dice-d20',
          label: 'yes',
          callback: (event, button, dialog) => {
            EquipmentDamage.resolveBreakingTest(item, Number($(button.form).find('[name="threshold"]').val()), category);
          }
        },
        {
          action: 'no',
          icon: 'fas fa-times',
          label: 'cancel',
        },
      ],
    }).render(true);
  }

  static async applyDamageLevelToItem(item, amount) {
    const damage = Math.ceil(item.system.structure.max * 0.25) * amount;
    await item.update({
      'system.structure.value': Math.max(0, item.system.structure.value - damage),
    });
  }

  static async absoluteDamageLevelToItem(item, amount) {
    const damage = Math.ceil(item.system.structure.max * 0.25) * amount;
    await item.update({
      'system.structure.value': Math.min(item.system.structure.value, Math.max(0, item.system.structure.max - damage)),
    });
  }

  static async resolveBreakingTest(item, threshold, category) {
    const roll = await DiceDSA5.manualRolls(await new Roll('1d20').evaluate(), _loc('WEAR.check', { category }));
    await DiceDSA5.showDiceSoNice(roll, game.settings.get('core', 'messageMode'));
    const damage = roll.total > threshold ? 1 : 0;
    await this.applyDamageLevelToItem(item, damage);
    const wear = EquipmentDamage.calculateWear(item);
    const infoMsg = await renderTemplate('systems/dsa5/templates/system/breakingtest.hbs', {
      wear,
      item,
      threshold,
      category,
      roll,
      result: _loc(`WEAR.${item.type}.${wear}`),
    });
    ChatMessage.create(DSA5_Utility.chatDataSetup(infoMsg));
  }

  static damageTooltip(item) {
    if (game.settings.get('dsa5', 'armorAndWeaponDamage')) {
      const wear = this.calculateWear(item);
      return {
        msg: _loc(`WEAR.${item.type}.${wear}`),
        css: `gearD damaged${wear}`,
      };
    }
    return { msg: '', css: '' };
  }

  static weaponWearModifier(weaponData) {
    if (game.settings.get('dsa5', 'armorAndWeaponDamage')) {
      switch (EquipmentDamage.calculateWear(weaponData)) {
        case 1:
          weaponData.attack -= 1;
          if (weaponData.parry) weaponData.parry -= 1;
          break;
        case 2:
          weaponData.attack -= 2;
          if (weaponData.parry) weaponData.parry -= 2;
          break;
        case 3:
        case 4:
          weaponData.attack = 0;
          if (weaponData.parry) weaponData.parry = 0;
      }
    }
  }

  static calculateWear(itemData) {
    if (!itemData.system.structure || Number(itemData.system.structure.max) <= 0) return 0;

    return Math.floor((1 - itemData.system.structure.value / itemData.system.structure.max) * 4);
  }
}
